mod support;
use support::*;
use birnam_abi::{Oop,id_protocol::{Operand,Outcome,NativeEntry}};
use std::{ffi::c_void,os::unix::ffi::OsStrExt,ptr};
unsafe extern "C" fn fail(_: *mut c_void,_:Oop,_:*const Operand,_:usize)->Outcome{Outcome::failed(6,941)}
fn main(){unsafe{
 let id=id();let ns=load(id,"bootstrap",&[Operand::bytes(directory().as_os_str().as_bytes())]);
 let named=|n:&[u8]|object(send(id,ns,b"at:",&[Operand::object(id.intern_name(n).unwrap())]));
 let roots=named(b"Roots");let gc=named(b"GC");
 send(id,gc,b"budget:",&[Operand::word(1024*1024)]);
 let callback=object(send(id,named(b"Object"),b"clone",&[]));retain(id,roots,callback);
 let vt=object(send(id,id.receiver,b"ensurePrivateVtableFor:",&[Operand::object(callback)]));
 install(id,vt,b"fail",fail,ptr::null_mut());
 send(id,named(b"Globals"),b"at:put:",&[Operand::object(id.intern_name(b"BlockFailureFixture").unwrap()),Operand::object(callback)]);
 let source=object(send(id,named(b"String"),b"fromBytes:",&[Operand::bytes(b"[BlockFailureFixture fail]")]));retain(id,roots,source);
 let method=object(send(id,named(b"Method"),b"fromNative:owner:",&[Operand::entry(NativeEntry::new(fail,ptr::null_mut())),Operand::object(named(b"nil"))]));retain(id,roots,method);
 let captures=object(send(id,named(b"Vector"),b"new",&[]));retain(id,roots,captures);
 let block=object(send(id,named(b"Block"),b"fromMethod:captures:",&[Operand::object(method),Operand::object(captures)]));retain(id,roots,block);
 let failure=id.send_named(block,b"value",&[]).unwrap_err();assert_eq!((failure.status,failure.detail),(6,941));
 let error=object(send(id,named(b"Codegen"),b"eval:",&[Operand::object(source)]));retain(id,roots,error);
 assert_eq!(object(send(id,error,b"kind",&[])),id.intern_name(b"nativeFailure").unwrap());
 println!("PRIOR_BLOCK_FAILURE_CONTRACT_OK: native synchronous Block preserves failure; source evaluation returns Error");
}}
